def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    payments = view.get('payments')
    services = view.get('services')
    if type(payments) is not list or type(services) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['payment_or_service_channel_unread'])
    service_ids = {}
    seen_service_keys = set()
    st = target_service(kernel)
    pt = target_payment(kernel)
    query_service_count = 0
    query_payment_count = 0
    for index, record in enumerate(services):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        local_id = record.get('local_id')
        worker = record.get('worker')
        employer = record.get('employer')
        if type(local_id) is not str or type(worker) is not str or type(employer) is not str or local_id in seen_service_keys:
            complete = False
            continue
        seen_service_keys.add(local_id)
        event = 'service_' + str(index)
        if record.get('is_query_service') is True:
            query_service_count += 1
            if type(st) is str:
                event = st
        service_ids[local_id] = event
        put(facts, 'service_', [event])
        put(facts, 'agent_', [event, worker])
        put(facts, 'patient_', [event, employer])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [event, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [event, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [event, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    seen_payment_keys = set()
    for index, record in enumerate(payments):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        local_id = record.get('local_id')
        payer = record.get('payer')
        payee = record.get('payee')
        if type(local_id) is not str or type(payer) is not str or type(payee) is not str or local_id in seen_payment_keys:
            complete = False
            continue
        seen_payment_keys.add(local_id)
        event = 'payment_' + str(index)
        if record.get('is_query_payment') is True:
            query_payment_count += 1
            if type(pt) is str:
                event = pt
        put(facts, 'payment_', [event])
        put(facts, 'agent_', [event, payer])
        put(facts, 'patient_', [event, payee])
        amount = record.get('amount')
        if type(amount) in (int, float):
            put(facts, 'amount_', [event, amount])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [event, record.get('medium')])
        if type(record.get('payment_date')) is str:
            put(facts, 'start_', [event, record.get('payment_date')])
        service_local_id = record.get('service_local_id')
        if type(service_local_id) is str:
            if service_local_id in service_ids:
                put(facts, 'purpose_', [event, service_ids[service_local_id]])
            else:
                complete = False
                add(reasons, 'payment_links_unknown_service')
    if type(st) is str and len(services) > 0 and query_service_count != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(payments) > 0 and query_payment_count != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    records = view.get('deductions')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['deduction_channel_unread'])
    seen = set()
    for index, record in enumerate(records):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        person = record.get('person')
        year = record.get('year')
        amount = record.get('amount')
        basis = record.get('basis')
        key = (person, year, amount, basis)
        if type(person) is not str or type(year) is not int or (amount is not None and type(amount) not in (int, float)) or basis not in ('itemized', 'other_chapter', 'section151_b_personal_exemption', 'section151_other', 'unstated'):
            complete = False
            continue
        if key in seen:
            continue
        seen.add(key)
        if basis in ('itemized', 'other_chapter'):
            event = 'deduction_' + str(index)
            put(facts, 'deduction_', [event])
            put(facts, 'agent_', [event, person])
            put(facts, 'start_', [event, str(year) + '-01-01'])
            put(facts, 'end_', [event, str(year) + '-12-31'])
            if type(amount) in (int, float):
                put(facts, 'amount_', [event, amount])
        elif basis == 'section151_b_personal_exemption':
            if type(amount) not in (int, float):
                complete = False
                add(reasons, 'section151_b_exemption_amount_unread')
            elif is_target_given(kernel, 's151_b'):
                complete = False
                add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            else:
                put(facts, 's151_b', [person, amount, year])
        elif basis == 'unstated':
            complete = False
            add(reasons, 'deduction_basis_unresolved')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    records = view.get('givens')
    boundaries = view.get('boundary_statements')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channel_unread'])
    seen = set()
    for record in records:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        name = record.get('predicate')
        args = record.get('arguments')
        polarity = record.get('polarity')
        if not valid_given(name, args) or polarity not in ('positive', 'negative'):
            complete = False
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        key = (name, tuple(args), polarity)
        if key in seen:
            continue
        seen.add(key)
        row = {'predicate': name, 'arguments': list(args)}
        add(negatives if polarity == 'negative' else facts, row)
    for record in boundaries:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        if record.get('kind') not in ('section151_d', 'section151_other', 'section63_f_other'):
            complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

