    binary = ('agent_', 'beneficiary_', 'country_', 'destination_', 'end_', 'location_', 'means_', 'patient_', 'purpose_', 'reason_', 'start_', 'type_')
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    rows = view.get('facts')
    negative_rows = view.get('negative_givens')
    if type(rows) is not list or type(negative_rows) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['source_native_channel_unread'])
    for row in rows:
        if not support(witnesses, row, public, True):
            complete = False
            continue
        name = row.get('predicate')
        args = row.get('arguments')
        valid = False
        if name in unary and type(args) is list and len(args) == 1 and type(args[0]) is str:
            valid = True
        elif name in binary and type(args) is list and len(args) == 2 and type(args[0]) is str and type(args[1]) is str:
            valid = True
        elif name == 'amount_' and type(args) is list and len(args) == 2 and type(args[0]) is str and type(args[1]) in (int, float):
            valid = True
        elif valid_given(name, args):
            valid = True
        if not valid:
            complete = False
            continue
        if valid_given(name, args) and is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        add(facts, {'predicate': name, 'arguments': list(args)})
    for row in negative_rows:
        if not support(witnesses, row, public, True):
            complete = False
            continue
        name = row.get('predicate')
        args = row.get('arguments')
        if not valid_given(name, args):
            complete = False
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        add(negatives, {'predicate': name, 'arguments': list(args)})
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)
